import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { GrillAnswer, GrillForm, GrillQuestion } from '../types'
import { firstRow, rowsFor, unwrap, wrap } from './field'
import type { Wrapped } from './field'

const TOOL_NAME = 'perguntar'
const TOOL = `mcp__grill-form__${TOOL_NAME}`
const PANE = 'grill-form'
const COMMAND = 'grill-form'
const EMPTY: GrillAnswer = { concordo: false, texto: '' }

const FORM = { plugin: 'grill-form', key: 'form' } as const
const form = atom(FORM, null)

const INSTRUCTIONS = `# Formulário de perguntas (grill-form)

Quando estiver conduzindo um grilling (skills grill-with-docs, grilling ou qualquer rodada de perguntas de decisão ao usuário, cada uma com uma recomendação sua), NÃO escreva as perguntas como lista no texto da resposta. Chame a ferramenta ${TOOL} com as perguntas da rodada: para cada uma, \`id\` (Q1, Q2...), \`titulo\` curto, \`pergunta\` completa e autocontida e \`recomendacao\` (a resposta que você sugere, com a consequência prática).

Antes da chamada, escreva no máximo um parágrafo curto de contexto (ex.: conflitos encontrados). Depois da chamada, encerre o turno sem repetir as perguntas: o usuário responde no formulário e as respostas chegam na próxima mensagem dele. No formulário, "Concordo" significa aceitar a sua recomendação; um comentário pode ser sugestão, informação nova, discordância ou pedido de esclarecimento. Uma pergunta sem resposta continua em aberto.`

const SCHEMA = {
  type: 'object',
  properties: {
    intro: {
      type: 'string',
      description: 'Contexto curto da rodada, exibido no topo do formulário (opcional).',
    },
    perguntas: {
      type: 'array',
      minItems: 1,
      items: {
        type: 'object',
        properties: {
          id: { type: 'string', description: 'Identificador curto: Q1, Q2...' },
          titulo: { type: 'string', description: 'Título curto da decisão.' },
          pergunta: { type: 'string', description: 'A pergunta completa e autocontida.' },
          recomendacao: {
            type: 'string',
            description: 'A resposta que você recomenda e o que ela implica. "Concordo" aceita exatamente isto.',
          },
        },
        required: ['id', 'titulo', 'pergunta', 'recomendacao'],
      },
    },
  },
  required: ['perguntas'],
}

type Engine = EngineInterface

const answerOf = (f: GrillForm, id: string): GrillAnswer => f.respostas[id] ?? EMPTY

type Mark = { glyph: string; label: string; color?: string }

const MARK = {
  agreed: { glyph: '●', label: 'concordo', color: 'success' },
  qualified: { glyph: '●', label: 'com ressalva', color: 'warning' },
  commented: { glyph: '◐', label: 'comentário', color: 'suggestion' },
  open: { glyph: '○', label: 'em aberto' },
} as const satisfies Record<string, Mark>

// Ids of one width, so the marks line up in the grid: Q3 → Q03 beside Q18; an id
// with no trailing number is padded with spaces. Display only: answers keep the id.
const chipLabels = (perguntas: GrillQuestion[]) => {
  const digits = Math.max(...perguntas.map(q => /\d+$/.exec(q.id)?.[0].length ?? 0))
  const padded = perguntas.map(q => [q.id, q.id.replace(/\d+$/, n => n.padStart(digits, '0'))] as const)
  const width = Math.max(...padded.map(([, label]) => label.length))
  return new Map(padded.map(([id, label]) => [id, label.padEnd(width)]))
}

const isAnswered = (a: GrillAnswer) =>
  a.ressalva ? a.texto.trim() !== '' : a.concordo || a.texto.trim() !== ''

// A ressalva only counts once it is written in the comment.
const isMissingRessalva = (a: GrillAnswer) => a.ressalva === true && a.texto.trim() === ''


const focusComment =($: Engine, id: string) =>
  $.ui.focus({ requestId: PANE, key: `texto-${id}` }).catch(() => undefined)

// Concordo: agrees and moves on; pressed again on a plain agreement, it clears it.
const agree = async ($: Engine, f: GrillForm, page: number) => {
  const q = f.perguntas[page]!
  const a = answerOf(f, q.id)
  if (a.concordo && !a.ressalva) return patch($, q.id, { concordo: false })
  await patch($, q.id, { concordo: true, ressalva: false })
  if (page < f.perguntas.length - 1) await goTo($, page + 1)
}

// Concordo com ressalva: stays, and hands the keys to the comment to write it.
const agreeWithRessalva = async ($: Engine, f: GrillForm, page: number) => {
  const q = f.perguntas[page]!
  if (answerOf(f, q.id).ressalva) return patch($, q.id, { concordo: false, ressalva: false })
  await patch($, q.id, { concordo: true, ressalva: true })
  await focusComment($, q.id)
}

const patch = ($: Engine, id: string, change: Partial<GrillAnswer>) =>
  update($, form, f =>
    f && { ...f, respostas: { ...f.respostas, [id]: { ...answerOf(f, id), ...change } } },
  )

const goTo = ($: Engine, page: number) =>
  update($, form, f => f && { ...f, page: Math.max(0, Math.min(page, f.perguntas.length - 1)) })

const parseQuestions = (input: unknown): GrillQuestion[] => {
  const raw = (input as { perguntas?: unknown })?.perguntas
  if (!Array.isArray(raw)) return []
  return raw
    .map((q, i) => ({
      id: String(q?.id ?? `Q${i + 1}`).trim(),
      titulo: String(q?.titulo ?? '').trim(),
      pergunta: String(q?.pergunta ?? '').trim(),
      recomendacao: String(q?.recomendacao ?? '').trim(),
    }))
    .filter(q => q.pergunta !== '')
}

const duplicateIds = (perguntas: GrillQuestion[]) => {
  const seen = new Set<string>()
  const repeated = new Set<string>()
  for (const { id } of perguntas) {
    if (id === '' || seen.has(id)) repeated.add(id === '' ? '(vazio)' : id)
    seen.add(id)
  }
  return [...repeated]
}

export const formatAnswers = (f: GrillForm): string => {
  const lines = f.perguntas.map(q => {
    const a = answerOf(f, q.id)
    const texto = a.texto.trim()
    const head = `**${q.id} — ${q.titulo}:**`
    if (a.ressalva) return `${head} Concordo com a recomendação, com ressalva: ${texto}`
    if (a.concordo && texto) return `${head} Concordo com a recomendação. Observação: ${texto}`
    if (a.concordo) return `${head} Concordo com a recomendação.`
    if (texto) return `${head} Não marquei "concordo". Comentário: ${texto}`
    return `${head} Sem resposta — manter em aberto.`
  })
  return `Respostas do formulário (grill-form):\n\n${lines.join('\n')}`
}

const explain = async ($: Engine, q: GrillQuestion) => {
  const current = await read($, form)
  const a = current ? answerOf(current, q.id) : EMPTY
  if (a.isExplaining) return
  if (a.explicacao) return patch($, q.id, { isExplanationOpen: !a.isExplanationOpen })

  await patch($, q.id, { isExplaining: true, isExplanationOpen: true })
  const ask =
    `No formulário de perguntas, o usuário clicou em "Me explica melhor" na pergunta ${q.id} — ${q.titulo}:\n` +
    `"${q.pergunta}"\nRecomendação dada: "${q.recomendacao}"\n\n` +
    'Explique em português do Brasil, de forma concisa e clara (até 5 frases curtas), a que essa pergunta se refere, ' +
    'por que ela importa e o que muda na prática conforme a resposta. Use termos simples, sem jargão desnecessário. ' +
    'Responda só com a explicação: não faça novas perguntas nem chame ferramentas.'

  const reply = await answer($, ask)
  if (reply.isAnswered) {
    await patch($, q.id, { isExplaining: false, explicacao: reply.text.trim() })
  } else {
    await patch($, q.id, { isExplaining: false, isExplanationOpen: false })
    $.ui.toast(`grill-form: não consegui gerar a explicação (${reply.reason}).`)
  }
}

const answer = async ($: Engine, prompt: string) => {
  const reply = await $.model.fork({ prompt })
  return reply.isAnswered ? reply : $.model.complete({ model: 'haiku', prompt })
}

// Another doubt after the explanation: the fork gets the explanation and the
// exchanges so far, so the person can keep asking until it is clear.
const followUp = async ($: Engine, q: GrillQuestion, duvida: string) => {
  const current = await read($, form)
  const a = current ? answerOf(current, q.id) : EMPTY
  const asked = duvida.trim()
  if (asked === '' || a.isExplaining || !a.explicacao) return

  const before = a.conversa ?? []
  await patch($, q.id, { isExplaining: true, duvida: '', conversa: [...before, { duvida: asked }] })
  const thread = before.map(one => `Usuário: "${one.duvida}"\nVocê: "${one.resposta ?? ''}"`).join('\n\n')
  const ask =
    `No formulário de perguntas, o usuário pediu explicação sobre a pergunta ${q.id} — ${q.titulo}:\n` +
    `"${q.pergunta}"\nRecomendação dada: "${q.recomendacao}"\n\n` +
    `Explicação que você deu: "${a.explicacao}"\n\n` +
    (thread ? `Conversa até aqui:\n${thread}\n\n` : '') +
    `Nova dúvida do usuário: "${asked}"\n\n` +
    'Responda em português do Brasil, de forma concisa e clara (até 5 frases curtas), só a essa dúvida, ' +
    'sem repetir o que já foi explicado. Use termos simples. ' +
    'Responda só com a resposta: não faça novas perguntas nem chame ferramentas.'

  const reply = await answer($, ask)
  if (reply.isAnswered) {
    await patch($, q.id, { isExplaining: false, conversa: [...before, { duvida: asked, resposta: reply.text.trim() }] })
  } else {
    await patch($, q.id, { isExplaining: false, conversa: before, duvida: asked })
    $.ui.toast(`grill-form: não consegui responder a dúvida (${reply.reason}).`)
  }
}

const send = async ($: Engine) => {
  const current = await read($, form)
  if (!current) return
  const missing = current.perguntas.findIndex(q => isMissingRessalva(answerOf(current, q.id)))
  if (missing >= 0) {
    const q = current.perguntas[missing]!
    $.ui.toast(`grill-form: escreva a ressalva de ${q.id} antes de enviar.`)
    await goTo($, missing)
    await focusComment($, q.id)
    return
  }
  await $.state.set(FORM, null)
  await $.ui.close({ id: PANE })
  await $.prompt.submit({ text: formatAnswers(current), asUser: true })
}

// The dock paints panes with the theme's composerSidebarBackground, which the
// ANSI themes set to blackBright: a mid gray on most palettes. Paint our own.
const paneBackground = async ($: Engine): Promise<string | undefined> => {
  const rows = await $.config.list().catch(() => [])
  const theme = String(rows.find(row => row.key === 'theme')?.value ?? '')
  if (!theme.includes('ansi')) return undefined
  return theme.startsWith('light') ? 'white' : 'black'
}

const openPane = (f: GrillForm) =>
  ({ id: PANE, title: `Perguntas (${f.perguntas.length})`, focus: true, rows: 24 }) as const

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.tool.register({
      name: TOOL_NAME,
      description:
        'Mostra ao usuário um formulário com as perguntas de decisão de um grilling (grill-with-docs), ' +
        'cada uma com sua recomendação. O usuário pode pedir explicação, concordar ou comentar; as respostas chegam ' +
        'na próxima mensagem dele. Use no lugar de listar as perguntas em texto e encerre o turno após chamar.',
      inputSchema: SCHEMA,
      isDeferred: false,
    })
    await $.command.register({
      name: 'grill-form',
      description: 'Reabre o formulário de perguntas do grilling',
    })

    return next(e)
  })

  on('prompt.compose', async ($, e, next) => {
    const composed = await next(e)
    if (!e.tools.includes(TOOL)) return composed

    return {
      sections: [...composed.sections, { id: 'grill-form:instructions', text: INSTRUCTIONS, scope: 'session' }],
    }
  })

  on('tool.check', { tool: 'mcp__grill-form__perguntar' }, async ($, e, next) => {
    const verdict = await next(e)
    if (verdict.decision !== 'ask' || e.ceiling === 'ask') return verdict

    return { ...verdict, decision: 'allow', reason: 'grill-form: só exibe um formulário ao usuário' }
  })

  on('tool.call', { tool: 'mcp__grill-form__perguntar' }, async ($, e) => {
    const perguntas = parseQuestions(e)
    if (perguntas.length === 0) {
      return { deny: 'grill-form: informe ao menos uma pergunta em `perguntas`, cada uma com id, titulo, pergunta e recomendacao.' }
    }
    // Why: as respostas são guardadas pelo id; dois iguais fariam um "Concordo" valer para as duas perguntas.
    const repeated = duplicateIds(perguntas)
    if (repeated.length > 0) {
      return { deny: `grill-form: ids repetidos ou vazios (${repeated.join(', ')}). Cada pergunta precisa de um id único; reenvie com Q1, Q2...` }
    }
    const intro = String((e as { intro?: unknown }).intro ?? '').trim()
    const fresh: GrillForm = { perguntas, respostas: {}, page: 0, ...(intro ? { intro } : {}) }
    await $.state.set(FORM, fresh)
    const opened = await $.ui.open(openPane(fresh))

    const where = opened.isPlaced
      ? 'O formulário está aberto na tela do usuário.'
      : `O painel ainda não coube na tela; o usuário pode abri-lo com /${COMMAND}.`

    return {
      result:
        `${where} ${perguntas.length} pergunta(s) enviada(s) ao formulário. ` +
        'Encerre o turno agora sem repetir as perguntas: as respostas chegarão na próxima mensagem do usuário.',
    }
  }).catch(() => ({
    deny: 'grill-form: não foi possível abrir o formulário; apresente as perguntas em texto nesta rodada.',
  }))

  on('command.run', { command: 'grill-form' }, async $ => {
    const current = await read($, form)
    if (!current) return { text: 'Nenhum formulário de perguntas pendente.' }
    await $.ui.open(openPane(current))

    return { text: 'Formulário de perguntas reaberto.' }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const ui = $.ui.resolve(e)
    const { Box, Text, Button, Markdown } = ui
    const Input = 'Input' in ui ? ui.Input : undefined
    const f = await read($, form)
    const backgroundColor = await paneBackground($)
    const fill = {
      backgroundColor,
      width: e.props.bodyColumns,
      minHeight: e.props.placement === 'dock' ? e.props.scroll.bodyRows : undefined,
      paddingX: 2,
      paddingY: 1,
    }

    if (!f) {
      return (
        <Box flexDirection="column" {...fill}>
          <Text dimColor>Nenhum formulário pendente.</Text>
          <Button key="close" role="dismiss" onPress={() => $.ui.close({ id: PANE })}>
            Fechar
          </Button>
        </Box>
      )
    }

    const total = f.perguntas.length
    const page = Math.min(f.page, total - 1)
    const q = f.perguntas[page]!
    const a = answerOf(f, q.id)
    const submitLabel = page < total - 1 ? 'avançar' : 'salvar'
    const answered = f.perguntas.filter(one => isAnswered(answerOf(f, one.id))).length
    const markOf = (one: GrillQuestion): Mark => {
      const answer = answerOf(f, one.id)
      if (answer.ressalva) return MARK.qualified
      if (answer.concordo) return MARK.agreed
      return answer.texto.trim() ? MARK.commented : MARK.open
    }

    // A field between two rules with ❯ before it, as the prompt box draws its own;
    // `width` is the room it sits in. The text is kept plain and drawn wrapped, the
    // field growing with it from `rows` to `maxRows`; `input` gets the wrapped text,
    // its rows and how to read what the field holds back as plain text.
    type Field = { title: string; width: number; rows: number; maxRows: number; plain: string; submitLabel: string }
    const fieldOf = (field: Field, input: (wrapped: Wrapped, rows: number, plain: (held: string) => string) => JSX.Element) => {
      const room = field.width - 2
      const wrapped = wrap(field.plain, firstRow(room, field.submitLabel), room - 1)
      return (
        <Box flexDirection="column">
          <Box flexDirection="row" columnGap={2} flexWrap="wrap">
            <Text color="suggestion" bold>
              {field.title}
            </Text>
            <Text dimColor>Ctrl+J quebra a linha</Text>
          </Box>
          <Text color="promptBorder">{'─'.repeat(Math.max(1, field.width))}</Text>
          <Box flexDirection="row">
            <Box width={2} flexShrink={0}>
              <Text color="suggestion">❯</Text>
            </Box>
            {input(wrapped, rowsFor(wrapped, field.rows, field.maxRows), held => unwrap(wrapped, held))}
          </Box>
          <Text color="promptBorder">{'─'.repeat(Math.max(1, field.width))}</Text>
        </Box>
      )
    }

    const glyph = (mark: Mark) => (
      <Text color={mark.color} dimColor={!mark.color}>
        {mark.glyph}
      </Text>
    )

    // A grid of fixed cells: "▸ " + the longest id + " " + the mark + a gap.
    // The room inside is the body less the outer padding, the dashed border and its padding.
    const labels = chipLabels(f.perguntas)
    const cellWidth = 2 + Math.max(...[...labels.values()].map(label => label.length)) + 1 + 1 + 3
    const perRow = Math.max(1, Math.floor((e.props.bodyColumns - 10) / cellWidth))
    const grid = Array.from({ length: Math.ceil(total / perRow) }, (_, r) =>
      f.perguntas.slice(r * perRow, (r + 1) * perRow),
    )

    return (
      <Box flexDirection="column" gap={1} {...fill}>
        {f.intro && <Text dimColor>{f.intro}</Text>}

        <Box borderStyle="dashed" borderColor="subtle" paddingX={2} paddingY={1} flexDirection="column" gap={1}>
          <Box flexDirection="column" rowGap={1}>
            {grid.map((row, r) => (
              <Box key={`chips-${r}`} flexDirection="row">
                {row.map(one => (
                  <Box key={`chip-${one.id}`} width={cellWidth} flexShrink={0} flexDirection="row">
                    {one.id === q.id ? (
                      <Text color="claude" bold>{`▸ ${labels.get(one.id)} `}</Text>
                    ) : (
                      <Text dimColor>{`  ${labels.get(one.id)} `}</Text>
                    )}
                    {glyph(markOf(one))}
                  </Box>
                ))}
              </Box>
            ))}
          </Box>
          <Box flexDirection="row" flexWrap="wrap" columnGap={4} justifyContent="center">
            <Text dimColor>{`${answered}/${total} respondidas`}</Text>
            {[MARK.agreed, MARK.qualified, MARK.commented, MARK.open].map(mark => (
              <Box key={`legend-${mark.label}`} flexDirection="row">
                {glyph(mark)}
                <Text dimColor>{` ${mark.label}`}</Text>
              </Box>
            ))}
          </Box>
        </Box>

        <Box flexDirection="column">
          <Text color="claude" bold>{`◆ ${q.id} — ${q.titulo}`}</Text>
          <Box paddingLeft={2}>
            <Text>{q.pergunta}</Text>
          </Box>
        </Box>

        <Box flexDirection="column">
          <Text color="success" bold>
            → Recomendação
          </Text>
          <Box paddingLeft={2}>
            <Text>{q.recomendacao}</Text>
          </Box>
        </Box>

        <Box flexDirection="row" gap={2}>
          <Button key="explain" onPress={() => explain($, q)}>
            {a.isExplaining ? 'Explicando…' : a.isExplanationOpen ? 'Ocultar explicação' : 'Me explica melhor'}
          </Button>
          <Button
            key="agree"
            variant={a.concordo && !a.ressalva ? 'primary' : 'secondary'}
            onPress={() => agree($, f, page)}
          >
            {a.concordo && !a.ressalva ? '✓ Concordo' : 'Concordo'}
          </Button>
          <Button
            key="agree-ressalva"
            variant={a.ressalva ? 'primary' : 'secondary'}
            onPress={() => agreeWithRessalva($, f, page)}
          >
            {a.ressalva ? '✓ Concordo com ressalva' : 'Concordo com ressalva'}
          </Button>
        </Box>

        {a.isExplanationOpen && (
          <Box borderStyle="round" borderColor="subtle" paddingX={1} flexDirection="column">
            {a.explicacao ? <Markdown text={a.explicacao} /> : <Text dimColor>Explicando…</Text>}
            {(a.conversa ?? []).map((one, i) => (
              <Box key={`conversa-${q.id}-${i}`} flexDirection="column" marginTop={1}>
                <Text color="suggestion">{`Você: ${one.duvida}`}</Text>
                {one.resposta ? <Markdown text={one.resposta} /> : <Text dimColor>Pensando…</Text>}
              </Box>
            ))}
            {Input && a.explicacao && (
              <Box marginTop={1}>
                {fieldOf(
                  {
                    title: 'Outra dúvida',
                    // The body less the outer padding, the box's border and its padding.
                    width: e.props.bodyColumns - 8,
                    rows: 2,
                    maxRows: 8,
                    plain: a.duvida ?? '',
                    submitLabel: 'perguntar',
                  },
                  (wrapped, rows, plain) => (
                    <Input
                      key={`duvida-${q.id}`}
                      rows={rows}
                      placeholder="pergunte o que ainda não ficou claro"
                      value={wrapped.text}
                      submitLabel="perguntar"
                      onInput={value => patch($, q.id, { duvida: plain(value) })}
                      onSubmit={value => followUp($, q, plain(value))}
                    />
                  ),
                )}
              </Box>
            )}
          </Box>
        )}

        {Input ? (
          fieldOf(
            {
              title: a.ressalva ? 'Ressalva' : 'Comentário',
              width: e.props.bodyColumns - 4,
              rows: 3,
              maxRows: 10,
              plain: a.texto,
              submitLabel,
            },
            (wrapped, rows, plain) => (
              <Input
                key={`texto-${q.id}`}
                rows={rows}
                placeholder={
                  a.ressalva
                    ? 'escreva a ressalva (obrigatório)'
                    : 'sugestão, informação ou dúvida sobre a pergunta (opcional)'
                }
                value={wrapped.text}
                submitLabel={submitLabel}
                onInput={value => patch($, q.id, { texto: plain(value) })}
                onSubmit={async value => {
                  const texto = plain(value)
                  await patch($, q.id, { texto })
                  if (a.ressalva && texto.trim() === '') return
                  if (page < total - 1) await goTo($, page + 1)
                }}
              />
            ),
          )
        ) : (
          <Text dimColor>Comentários só podem ser digitados no terminal ou no desktop.</Text>
        )}

        {isMissingRessalva(a) && (
          <Text color="warning">Escreva a ressalva no comentário para concluir esta pergunta.</Text>
        )}

        <Box flexDirection="row" gap={2} flexWrap="wrap">
          {page > 0 && (
            <Button key="prev" onPress={() => goTo($, page - 1)}>
              ◀ Anterior
            </Button>
          )}
          {page < total - 1 && (
            <Button key="next" onPress={() => goTo($, page + 1)}>
              Próxima ▶
            </Button>
          )}
          <Button
            key="agree-all"
            dimColor
            onPress={() =>
              update($, form, cur =>
                cur && {
                  ...cur,
                  respostas: Object.fromEntries(
                    cur.perguntas.map(one => [one.id, { ...answerOf(cur, one.id), concordo: true }]),
                  ),
                },
              )
            }
          >
            Concordo com todas
          </Button>
          <Button key="send" variant="primary" onPress={() => send($)}>
            {`Enviar respostas (${answered}/${total})`}
          </Button>
