// The engine's Input does not wrap: a line wider than the field is cut with "…".
// So the text is wrapped as it is drawn: a space past the field's edge is drawn
// as a newline, a soft one, which reads back as the space it was. The text kept
// is always the plain one; what the field holds is `wrap(plain)`.

export type Wrapped = { text: string; soft: number[] }

// Greedy, at spaces: the first row is `first` wide (the engine's hint sits
// beside it), the others `rest`. A word longer than a row is left to be cut.
export const wrap = (plain: string, first: number, rest: number): Wrapped => {
  const chars = plain.split('')
  const soft: number[] = []
  let lineStart = 0
  let width = first
  let lastSpace = -1
  for (let i = 0; i < chars.length; i++) {
    if (chars[i] === '\n') {
      lineStart = i + 1
      width = rest
      lastSpace = -1
      continue
    }
    if (chars[i] === ' ') lastSpace = i
    if (i - lineStart >= width && lastSpace >= lineStart) {
      chars[lastSpace] = '\n'
      soft.push(lastSpace)
      lineStart = lastSpace + 1
      width = rest
      lastSpace = -1
    }
  }
  return { text: chars.join(''), soft }
}

// What the field now holds, read back as plain text: the soft newlines of what
// was drawn before the edit stay where they were, those after it move with the
// text, and one the edit touched is gone (a backspace over it eats the space).
export const unwrap = (before: Wrapped, held: string): string => {
  const a = before.text
  let start = 0
  while (start < a.length && start < held.length && a[start] === held[start]) start++
  let end = 0
  while (end < a.length - start && end < held.length - start && a[a.length - 1 - end] === held[held.length - 1 - end]) end++
  const shift = held.length - a.length
  const soft = new Set(before.soft.flatMap(i => (i < start ? [i] : i >= a.length - end ? [i + shift] : [])))
  return held
    .split('')
    .map((char, i) => (char === '\n' && soft.has(i) ? ' ' : char))
    .join('')
}

// The rows a field of `min` to `max` rows takes to show the wrapped text.
export const rowsFor = (wrapped: Wrapped, min: number, max: number) =>
  Math.min(max, Math.max(min, wrapped.text.split('\n').length))

// Room on the first row: the field less the engine's hint (" ⏎ <label> · shift+⏎
// new line", the longest spelling) and the cursor's cell.
export const firstRow = (width: number, submitLabel: string) =>
  Math.max(8, width - ` ⏎ ${submitLabel} · shift+⏎ new line`.length - 2)

